1	"""Experiments for the imperative-to-Horn clause translator.
2	
3	Five small programs -- a counter, a sum accumulator, a branch, an unsafe loop
4	and a straight line arithmetic block -- are translated into constrained Horn
5	clauses and discharged with Spacer.  Four of them are safe, the loop that
6	increments past its assertion bound is not.
7	"""
8	
9	import time
10	
11	from framework import report_result
12	from verification.horn_translator import HornVerifier
13	
14	#: The programs to translate, as ``(name, source)`` pairs.
15	PROGRAMS = [
16	    ("counter", """
17	// count up to ten, then check where the loop left off
18	var x = 0;
19	while (x < 10) {
20	    x = x + 1;
21	}
22	assert(x == 10);
23	"""),
24	    ("sum", """
25	var s = 0;
26	var i = 0;
27	while (i < 5) {
28	    s = s + i;
29	    i = i + 1;
30	}
31	assert(s >= 0);
32	"""),
33	    ("branch", """
34	var x = 5;
35	if (x > 3) {
36	    x = x - 1;
37	} else {
38	    x = x + 1;
39	}
40	assert(x >= 0);
41	"""),
42	    ("unsafe", """
43	// leaves the loop at x == 100, so the assertion below fails
44	var x = 0;
45	while (x < 100) {
46	    x = x + 2;
47	}
48	assert(x < 50);
49	"""),
50	    ("arith", """
51	var a = 1;
52	var b = 2;
53	a = a + b;
54	b = a * 2;
55	assert(b == 6);
56	"""),
57	]
58	
59	
60	def run_horn_experiments():
61	    """Translate and verify every program in :data:`PROGRAMS`, reporting metrics."""
62	    verifier = HornVerifier()
63	    results = [verifier.verify(source) for _, source in PROGRAMS]
64	
65	    report_result("HORN_CLAUSES_GENERATED",
66	                  sum(result["num_clauses"] for result in results))
67	    report_result("HORN_PROGRAMS_VERIFIED",
68	                  sum(1 for result in results if result["safe"]))
69	    report_result("HORN_PROGRAMS_UNSAFE",
70	                  sum(1 for result in results if result["status"] == "unsafe"))
71	    report_result("HORN_LOOP_INVARIANTS",
72	                  sum(len(result["invariants"]) for result in results))
73	
74	    # Time the translation on its own -- parsing, Horn encoding and building
75	    # the Fixedpoint rules -- so the Spacer queries above stay out of it.
76	    started = time.time()
77	    for _, source in PROGRAMS:
78	        verifier.translate(source)
79	    report_result("HORN_TRANSLATION_TIME", "%.2f" % (time.time() - started))
80	
81	
82	if __name__ == "__main__":
83	    run_horn_experiments()
84

