def _ensure_state(self, node):
    """Derive the state vector from `node` when the encoder is still empty.

    :meth:`encode_program` discovers the variables of the whole program up
    front.  Each ``encode_*`` method is usable on its own as well, so when
    one of them is the first call on a fresh encoder the statement it was
    handed defines the vector its relations range over.  Once any clause
    has been emitted the vector is fixed, because the relations already
    built are applications of exactly that vector.
    """
    if self.clauses or self.program_vars:
        return
    self._collect_variables(node)
    self._consts = {name: z3.Int(name) for name in self.program_vars}
